{
  "root": "main_stack",
  "state": {
    "schedule_rows": [
      {
        "date": "October 15, 2025",
        "time": "09:00 - 10:30",
        "event": "Opening Keynote by Sarah Chen",
        "location": "Main Hall"
      },
      {
        "date": "October 15, 2025",
        "time": "11:00 - 12:30",
        "event": "[Conflict] Ethics in AI",
        "location": "Room A"
      },
      {
        "date": "October 15, 2025",
        "time": "11:00 - 12:30",
        "event": "Quantum Computing",
        "location": "Room B"
      },
      {
        "date": "October 15, 2025",
        "time": "14:00 - 17:00",
        "event": "Hands-on React Workshop",
        "location": "Lab 1"
      },
      {
        "date": "October 16, 2025",
        "time": "10:00 - 11:30",
        "event": "The Future of Web Development",
        "location": "Main Hall"
      },
      {
        "date": "October 16, 2025",
        "time": "13:00 - 14:30",
        "event": "Networking Luncheon",
        "location": "Garden Terrace"
      },
      {
        "date": "October 16, 2025",
        "time": "15:00 - 16:30",
        "event": "Cybersecurity Deep Dive",
        "location": "Room A"
      },
      {
        "date": "October 17, 2025",
        "time": "09:00 - 11:00",
        "event": "Startup Pitch Competition",
        "location": "Main Hall"
      },
      {
        "date": "October 17, 2025",
        "time": "12:00 - 13:30",
        "event": "Closing Ceremony and Awards",
        "location": "Main Hall"
      }
    ]
  },
  "elements": {
    "main_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md"
      },
      "children": [
        "title_h1",
        "intro_text",
        "schedule_section_heading_stack",
        "berlin_image",
        "schedule_table",
        "conflict_resolution_heading",
        "conflict_resolution_text",
        "quick_actions_heading",
        "quick_actions_stack",
        "sources_heading",
        "sources_stack"
      ]
    },
    "title_h1": {
      "type": "Text",
      "props": {
        "text": "Global Tech Summit 2025: Berlin",
        "variant": "h1"
      },
      "children": []
    },
    "intro_text": {
      "type": "Text",
      "props": {
        "text": "This structured itinerary for the Berlin summit identifies key sessions across AI, Quantum Computing, and Cybersecurity, while highlighting potential scheduling conflicts."
      },
      "children": []
    },
    "schedule_section_heading_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "schedule_section_heading",
        "calendar_icon"
      ]
    },
    "schedule_section_heading": {
      "type": "Text",
      "props": {
        "text": "Event Schedule & Conflicts",
        "variant": "h2"
      },
      "children": []
    },
    "calendar_icon": {
      "type": "Icon",
      "props": {
        "name": "https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/icons/calendar.svg"
      },
      "children": []
    },
    "berlin_image": {
      "type": "Image",
      "props": {
        "url": "https://upload.wikimedia.org/wikipedia/commons/thumb/8/83/Brandenburger_Tor_abends.jpg/1200px-Brandenburger_Tor_abends.jpg",
        "fit": "cover"
      },
      "children": []
    },
    "schedule_table": {
      "type": "Table",
      "props": {
        "statePath": "/schedule_rows",
        "columns": [
          {
            "key": "date",
            "label": "Date"
          },
          {
            "key": "time",
            "label": "Time"
          },
          {
            "key": "event",
            "label": "Event"
          },
          {
            "key": "location",
            "label": "Location"
          }
        ],
        "domain": "schedule",
        "preferredPresentation": "cards",
        "primaryColumn": "event",
        "highlightColumns": [
          "time",
          "location"
        ]
      },
      "children": []
    },
    "conflict_resolution_heading": {
      "type": "Text",
      "props": {
        "text": "Conflict Resolution Guide",
        "variant": "h2"
      },
      "children": []
    },
    "conflict_resolution_text": {
      "type": "Text",
      "props": {
        "text": "October 15 (11:00 AM): Attendees must choose between the high-level policy discussion on AI Ethics in Room A or the technical deep dive into Quantum Computing in Room B."
      },
      "children": []
    },
    "quick_actions_heading": {
      "type": "Text",
      "props": {
        "text": "Quick Actions",
        "variant": "h2"
      },
      "children": []
    },
    "quick_actions_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "md",
        "justify": "start",
        "wrap": "wrap"
      },
      "children": [
        "vote_button",
        "lab_registration_button"
      ]
    },
    "vote_button": {
      "type": "Button",
      "props": {
        "label": "Vote for Pitches"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://globaltech-berlin.com/startup-vote"
          }
        }
      },
      "children": []
    },
    "lab_registration_button": {
      "type": "Button",
      "props": {
        "label": "Lab Registration"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://globaltech-berlin.com/react-workshop"
          }
        }
      },
      "children": []
    },
    "sources_heading": {
      "type": "Text",
      "props": {
        "text": "Sources",
        "variant": "h2"
      },
      "children": []
    },
    "sources_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "official_agenda_button",
        "berlin_tech_hub_button"
      ]
    },
    "official_agenda_button": {
      "type": "Button",
      "props": {
        "label": "Official Summit Agenda"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://globaltech-berlin.com/schedule"
          }
        }
      },
      "children": []
    },
    "berlin_tech_hub_button": {
      "type": "Button",
      "props": {
        "label": "Berlin Tech Hub"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.berlin.de/en/business/"
          }
        }
      },
      "children": []
    }
  }
}
